// 6.3.1.1 (part 2) - only treat messages that look like a new support request as tickets,
// not every message in the channel. Simple heuristic, flagged as placeholder logic.
const msg = $input.item.json;
const text = (msg.text || '').trim();

// Skip bot messages / empty messages / thread replies (only root messages become tickets)
const isCandidate = text.length > 5 && !msg.bot_id && !msg.thread_ts;

return [{
  json: {
    slack_channel: msg.channel,
    slack_user: msg.user,
    slack_ts: msg.ts,
    message_text: text,
    is_candidate: isCandidate
  }
}];

