ALTER TABLE clients_master ADD COLUMN IF NOT EXISTS support_ticket_count INTEGER DEFAULT 0;

UPDATE clients_master
SET support_ticket_count = COALESCE(support_ticket_count, 0) + 1,
    updated_at = now()
WHERE id = {{ $('Attempt Client Match').item.json.client_id }};

